query:
-- KY-1: James Comer won R primary (88.1%), not David Sims
UPDATE house_races SET candidate2_name = 'James Comer', candidate2_party = 'R'
WHERE state_code = 'KY' AND district = '1';

-- KY-2: Brett Guthrie won R primary (85.4%); Wingfield is D
UPDATE house_races SET candidate2_name = 'Brett Guthrie', candidate2_party = 'R'
WHERE state_code = 'KY' AND district = '2';

-- KY-5: Harold Rogers won R primary (77.4%), not Kevin Smith
UPDATE house_races SET candidate2_name = 'Harold Rogers', candidate2_party = 'R'
WHERE state_code = 'KY' AND district = '5';

SELECT state_code, district, candidate1_name, candidate1_party, candidate2_name, candidate2_party 
FROM house_races WHERE state_code = 'KY' ORDER BY district;

